const brandProfile = $('Fetch Brand Profile').first().json;
const layouts = $('Fetch Reference Layouts').all();
const webhookBody = $('Webhook').first().json.body;

if (!layouts.length) throw new Error('No reference layouts found for category: ' + webhookBody.referenceCategoryId);

// Pick a random layout prompt
const randomLayout = layouts[Math.floor(Math.random() * layouts.length)];
const layoutPrompt = randomLayout.json.prompt;
const layoutId = randomLayout.json.id;

const headline = webhookBody.headline;
const cta = webhookBody.cta;
const brandId = webhookBody.brandId;
const referenceCategoryId = webhookBody.referenceCategoryId;
const logoUrl = brandProfile.logo_url || null;
const brandStyle = brandProfile.style_prompt || '';

const prompt = `LAYOUT REFERENCE (composition and positioning only — do NOT use colors, fonts, or visual elements from this):\n${layoutPrompt}\n\nBRAND STYLE (use these colors, fonts, and visual elements):\n${brandStyle}\n\nGenerate a professional social media post image following the layout above using the brand style described.\nDo NOT include any logo or brand mark anywhere in the image — a logo will be overlaid separately in post-processing.\nLeave the top-left area (approximately 260px wide x 130px tall) as a clean background for the logo overlay.\n\nHeadline: ${headline}\nCTA: ${cta}`;

return [{
  json: {
    brandId,
    referenceCategoryId,
    headline,
    cta,
    logoUrl,
    layoutId,
    storagePath: `${brandId}/${Date.now()}_post.png`,
    requestBody: JSON.stringify({
      model: 'gpt-image-1.5',
      prompt,
      size: '1024x1024',
      quality: 'high',
      n: 1
    })
  }
}];

const turn2 = $('Generate Image').first().json;
const meta = $('Build Prompt').first().json;

const imageData = turn2.data && turn2.data[0];
if (!imageData || !imageData.b64_json) throw new Error('No image data in response: ' + JSON.stringify(turn2));

const base64 = imageData.b64_json;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(base64, 'base64'),
  'post.png',
  'image/png'
);

return [{
  json: {
    brandId: meta.brandId,
    referenceCategoryId: meta.referenceCategoryId,
    headline: meta.headline,
    cta: meta.cta,
    storagePath: meta.storagePath,
    imageUrl: null /* set after ImageKit upload */,
    logoUrl: meta.logoUrl,
    layoutId: meta.layoutId
  },
  binary: { data: binaryData }
}];

const item = $input.first();
const meta = item.json;
const mime = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/png';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileName = (meta.storagePath || meta.fileName || ('upload-' + Date.now() + '.png')).toString().split('/').pop();
const dataUrl = 'data:' + mime + ';base64,' + buffer.toString('base64');

const boundary = '----n8nIkBoundary' + Date.now().toString(36);
const parts = [];
function addField(name, value) {
  parts.push(
    '--' + boundary + '\r\n' +
    'Content-Disposition: form-data; name="' + name + '"\r\n\r\n' +
    value + '\r\n'
  );
}
addField('file', dataUrl);
addField('fileName', fileName);
addField('folder', '/generated-posts');
addField('useUniqueFileName', 'true');
parts.push('--' + boundary + '--\r\n');
const body = parts.join('');

let uploaded;
try {
  uploaded = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://upload.imagekit.io/api/v1/files/upload',
    headers: {
      Authorization: 'Basic __IMAGEKIT_BASIC_AUTH__',
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
    },
    body,
    timeout: 120000,
  });
} catch (err) {
  throw new Error('ImageKit httpRequest failed: ' + (err.message || String(err)));
}

if (typeof uploaded === 'string') {
  try { uploaded = JSON.parse(uploaded); } catch (_) {}
}
if (!uploaded || !uploaded.url) {
  throw new Error('ImageKit upload failed: ' + JSON.stringify(uploaded));
}

return [{ json: Object.assign({}, meta, uploaded) }];

const uploaded = $('Upload to ImageKit').first().json;
const meta = $('Extract and Prepare Image').first().json;
const endpoint = '__IMAGEKIT_URL_ENDPOINT__'.replace(/\/$/, '');
let imageUrl = uploaded.url;
if (!imageUrl) throw new Error('ImageKit upload failed: ' + JSON.stringify(uploaded));

// Optional logo overlay when brand logo is already on ImageKit
const logoUrl = meta.logoUrl;
if (logoUrl && typeof logoUrl === 'string' && logoUrl.startsWith(endpoint)) {
  let logoPath = logoUrl.slice(endpoint.length).replace(/^\/tr:[^/]+/, '').split('?')[0];
  if (logoPath.startsWith('/')) logoPath = logoPath.slice(1);
  const overlayPath = logoPath.replace(/\//g, '@@');
  const basePath = String(uploaded.filePath || '').replace(/^\//, '');
  if (overlayPath && basePath) {
    imageUrl = endpoint + '/tr:l-image,i-' + overlayPath + ',w-220,lx-40,ly-40,l-end/' + basePath;
  }
}

return [{
  json: {
    ...meta,
    imageUrl,
    imageKitFileId: uploaded.fileId || null,
    imageKitFilePath: uploaded.filePath || null,
  }
}];
